import java.util.List;
import java.util.stream.Stream;

public class StreamVsCollection {
    public static void main(String[] args) {
        List<String> names = List.of("amy", "bob", "cat"); // Collection: stores data

        Stream<String> s = names.stream();                  // Stream: processes data
        long count = s.filter(n -> n.length() == 3).count(); // terminal triggers work
        System.out.println(count); // 3

        // s.forEach(...); // would throw IllegalStateException: already consumed
    }
}
