import java.util.List;

public class IntermediateVsTerminal {
    public static void main(String[] args) {
        var nums = List.of(1, 2, 3, 4, 5, 6);

        var result = nums.stream()
            .filter(n -> n % 2 == 0)  // intermediate: lazy, returns a Stream
            .map(n -> n * 10)         // intermediate: lazy, returns a Stream
            .toList();                // terminal: triggers execution, returns a List

        System.out.println(result); // [20, 40, 60]
    }
}
