import java.util.stream.IntStream;

public class ParallelStreamDemo {
    public static void main(String[] args) {
        long seq = IntStream.rangeClosed(1, 1_000_000)
            .asLongStream()
            .sum();

        long par = IntStream.rangeClosed(1, 1_000_000)
            .asLongStream()         // avoid overflowing an int sum
            .parallel()
            .sum();                 // associative reduction, safe to split

        System.out.println(seq + " == " + par);
    }
}
```

Both pipelines must produce the same value. Whether the parallel version is faster depends on the machine, source size, pool load, and surrounding work.

import java.util.List;
import java.util.stream.Collectors;

public class PeekDemo {
    public static void main(String[] args) {
        var orders = List.of(
            new Order(1L, "Laptop", 500),
            new Order(2L, "Mouse", 25),
            new Order(3L, "Monitor", 300)
        );

        // Using peek to debug the pipeline
        var expensiveItems = orders.stream()
            .peek(o -> System.out.println("Original: " + o))
            .filter(o -> o.price() > 100)
            .peek(o -> System.out.println("After filter: " + o))
            .map(Order::item)
            .peek(item -> System.out.println("After map: " + item))
            .collect(Collectors.toList());

        // peek without terminal op does nothing
        orders.stream()
            .peek(o -> System.out.println("This won't print"));
    }
}

